const workflowPaths = new Set([
  '/approvals',
  '/reports/daily',
  '/reports/supervisor-update',
  '/documents',
  '/finance',
  '/materials',
  '/hr',
  '/me/hr',
  '/hr/site-attendance'
]);

export function workflowLink(body: string, origin = window.location.origin) {
  // Workflow notifications end with the link generated by append_link on the API.
  const match = /\n\n(Open [a-z ]+): (https?:\/\/\S+)$/.exec(body);
  if (!match) return null;
  try {
    const url = new URL(match[2]);
    if (
      url.origin !== origin ||
      url.username ||
      url.password ||
      !workflowPaths.has(url.pathname)
    ) {
      return null;
    }
    return { message: body.slice(0, match.index), label: match[1], to: url.pathname + url.search };
  } catch {
    return null;
  }
}

export function isNotificationActionable(notification: {
  is_actionable?: boolean | null;
  superseded_at?: string | null;
}): boolean {
  return notification.superseded_at == null && notification.is_actionable !== false;
}

export function notificationWorkflowLink(
  notification: {
    body: string;
    is_actionable?: boolean | null;
    superseded_at?: string | null;
  },
  origin = window.location.origin
) {
  return isNotificationActionable(notification) ? workflowLink(notification.body, origin) : null;
}
